create table if not exists public.external_data_datasets (id uuid primary key default gen_random_uuid(), source_id uuid references public.external_data_sources(id) on delete cascade, external_dataset_id text not null, title text not null, publisher text, description text, landing_url text, license_url text, license_name text, access_level text, format text, resource_url text, spatial boolean not null default false, geography text, keywords text[] not null default '{}', schema_hint jsonb not null default '{}'::jsonb, import_policy text not null default 'review', status text not null default 'discovered', last_cataloged_at timestamptz not null default now(), last_imported_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(source_id, external_dataset_id)); create table if not exists public.external_import_jobs (id uuid primary key default gen_random_uuid(), dataset_id uuid references public.external_data_datasets(id) on delete set null, source_id uuid references public.external_data_sources(id) on delete set null, job_type text not null, status text not null default 'queued', query jsonb not null default '{}'::jsonb, records_seen integer not null default 0, records_imported integer not null default 0, observations_imported integer not null default 0, errors integer not null default 0, error_detail jsonb not null default '[]'::jsonb, started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now()); create index if not exists idx_external_data_datasets_source_status on public.external_data_datasets(source_id,status); create index if not exists idx_external_data_datasets_spatial on public.external_data_datasets(spatial); create index if not exists idx_external_import_jobs_status on public.external_import_jobs(status,created_at desc); create or replace function public.search_public_data_catalog(p_query text,p_limit integer default 25) returns table(id uuid,title text,publisher text,landing_url text,license_name text,resource_url text,spatial boolean,geography text,keywords text[],status text) language sql stable security definer set search_path=public as $$ select d.id,d.title,d.publisher,d.landing_url,d.license_name,d.resource_url,d.spatial,d.geography,d.keywords,d.status from public.external_data_datasets d where p_query is null or p_query='' or d.title ilike '%'||p_query||'%' or coalesce(d.description,'') ilike '%'||p_query||'%' or exists(select 1 from unnest(d.keywords) k where k ilike '%'||p_query||'%') order by d.spatial desc,d.last_cataloged_at desc limit greatest(1,least(p_limit,100)); $$; revoke all on function public.search_public_data_catalog(text,integer) from public; grant execute on function public.search_public_data_catalog(text,integer) to authenticated; insert into public.external_data_sources (source_key,name,source_url,attribution_text,license_name,license_url,active) select 'datagov','Data.gov Catalog','https://catalog.data.gov/','U.S. Government open-data catalog','Public/open-data varies by publisher','https://resources.data.gov/catalog-api/',true where not exists(select 1 from public.external_data_sources where source_key='datagov');
